insert into public.ls_items (code, grp, title, descr, sort, active, unit, div_code, refs) values ($t$LS-95$t$, 'مركز نموذج المسار الرابع', $t$وحدة الحلقة الرئيسية (RMU) والمحول وكابلات الجهد المتوسط$t$, $t$توريد وتركيب واختبار وتشغيل وحدة الحلقة الرئيسية (RMU) للجهد المتوسط، ومحول التوزيع بالقدرة حسب دراسة الأحمال المعتمدة ونسبة الاحتياطي، وكابلات الجهد المتوسط بنهاياتها ووصلاتها، وفق اشتراطات الشركة السعودية للكهرباء ومواصفاتها؛ شاملاً غرفة المحول أو قاعدته وفتحات التهوية والتأريض والحماية، والاختبارات المصنعية والموقعية، والتسليم والتوصيل مع الشركة. المصنّعون المعتمدون من القائمة المعتمدة لدى الشركة السعودية للكهرباء: وحدة الحلقة Lucy أو Schneider أو Hitachi Energy، والمحول الفنار أو الشركة السعودية للمحولات أو Hitachi Energy. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 805, true, 'مقطوعية', '26', array[$t$26 13 16$t$,$t$26 12 16$t$,$t$26 12 19$t$,$t$26 05 13$t$,$t$26 05 14$t$]::text[]) on conflict (code) do nothing;
insert into public.ls_items (code, grp, title, descr, sort, active, unit, div_code, refs) values ($t$LS-96$t$, 'مركز نموذج المسار الرابع', $t$المولد الاحتياطي ومفتاح التحويل الآلي$t$, $t$توريد وتركيب وتشغيل مولد ديزل احتياطي بمظلة صامتة بالقدرة حسب دراسة الأحمال الأساسية للمركز (الإنارة والقوى الحرجة، التكييف للمناطق الحرجة، مضخات الحريق والمياه، المصاعد، الغازات الطبية، الأنظمة التقنية) مع احتياطي مستقبلي، بخزان وقود يكفي التشغيل المتواصل للمدة المعتمدة، ونظام العادم والكاتم، والقاعدة وعوازل الاهتزاز، ولوحة التحكم والمراقبة عن بعد والربط بنظام إدارة المبنى؛ ومفتاح التحويل الآلي (ATS) بالسعة المناسبة؛ مع اختبار التحميل الكامل بحمل صناعي (Load Bank) وزمن التحويل، وفق NFPA 110 ومتطلبات الدفاع المدني. المصنّعون المعتمدون: المولد Cummins أو Caterpillar أو FG Wilson أو MTU، ومفتاح التحويل ASCO أو Cummins أو ABB. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 806, true, 'مقطوعية', '26', array[$t$26 32 13$t$,$t$26 32 23$t$,$t$26 32 26$t$,$t$26 32 29$t$,$t$26 36 23$t$]::text[]) on conflict (code) do nothing;
insert into public.materials (code, category, name, makers, spec, rule, ls_codes, std_codes, sort) values ($t$M-39$t$, $t$الميكانيكا$t$, $t$الغازات الطبية$t$, array[$t$BeaconMedaes$t$,$t$Amico$t$,$t$Dräger$t$,$t$Atlas Copco$t$]::text[], $t$Atlas Copco لمحطات الهواء والشفط فقط$t$, $t$list$t$, array[$t$LS-76$t$]::text[], array[$t$HTM 02-01$t$,$t$NFPA 99$t$]::text[], 390) on conflict (code) do nothing;
insert into public.materials (code, category, name, makers, spec, rule, ls_codes, std_codes, sort) values ($t$M-40$t$, $t$الكهرباء$t$, $t$المولدات ومفاتيح التحويل الآلي$t$, array[$t$Cummins$t$,$t$Caterpillar$t$,$t$FG Wilson$t$,$t$MTU$t$,$t$ASCO$t$,$t$ABB$t$]::text[], $t$مفاتيح التحويل: ASCO أو Cummins أو ABB$t$, $t$list$t$, array[$t$LS-96$t$]::text[], array[$t$NFPA 110$t$]::text[], 400) on conflict (code) do nothing;
insert into public.materials (code, category, name, makers, spec, rule, ls_codes, std_codes, sort) values ($t$M-41$t$, $t$الكهرباء$t$, $t$وحدات الحلقة الرئيسية والمحولات$t$, array[$t$Lucy$t$,$t$Schneider$t$,$t$Hitachi Energy$t$,$t$الفنار$t$,$t$الشركة السعودية للمحولات$t$]::text[], $t$من القائمة المعتمدة لدى الشركة السعودية للكهرباء$t$, $t$list$t$, array[$t$LS-95$t$]::text[], '{}'::text[], 410) on conflict (code) do nothing;
insert into public.guide_cards (key, code_label, ls_codes, section, kind, sort, title, en, rule, approved, why) values ($t$G-30$t$, $t$LS-76$t$, array[$t$LS-76$t$]::text[], $t$الأنظمة الكهروميكانيكية والتقنية$t$, 'row', 245, $t$الغازات الطبية$t$, $t$Medical Gases$t$, 'list', $t$BeaconMedaes · Amico · Dräger · Atlas Copco (محطات الهواء والشفط)$t$, $t$نظام يمس سلامة المرضى مباشرة: مصنّعون متخصصون، واختبارات HTM 02-01 / NFPA 99 قبل التشغيل، ودعم فني لما بعد البيع.$t$) on conflict (key) do nothing;
insert into public.guide_cards (key, code_label, ls_codes, section, kind, sort, title, en, rule, approved, why) values ($t$G-31$t$, $t$LS-95$t$, array[$t$LS-95$t$]::text[], $t$الأنظمة الكهروميكانيكية والتقنية$t$, 'row', 246, $t$وحدات الحلقة الرئيسية والمحولات$t$, $t$Ring Main Units and Transformers$t$, 'list', $t$Lucy · Schneider · Hitachi Energy · الفنار · الشركة السعودية للمحولات$t$, $t$تستلمها الشركة السعودية للكهرباء، فلا يُقبل إلا ما في قائمتها المعتمدة.$t$) on conflict (key) do nothing;
insert into public.guide_cards (key, code_label, ls_codes, section, kind, sort, title, en, rule, approved, why) values ($t$G-32$t$, $t$LS-96$t$, array[$t$LS-96$t$]::text[], $t$الأنظمة الكهروميكانيكية والتقنية$t$, 'row', 247, $t$المولدات ومفاتيح التحويل الآلي$t$, $t$Generators and Automatic Transfer Switches$t$, 'list', $t$Cummins · Caterpillar · FG Wilson · MTU — مفاتيح التحويل: ASCO · Cummins · ABB$t$, $t$التشغيل الاحتياطي للأحمال الحرجة: علامات معروفة بوكلاء صيانة وقطع غيار في المملكة، واختبار تحميل كامل وفق NFPA 110.$t$) on conflict (key) do nothing;
insert into public.i18n (k, src, en) values
  ($t$3fedc71fb4c95e0b9446e49b12060e4a54b2836afbf5bada793daf8c91129d0c$t$, $t$يشمل مخططات الورشة المعمارية والميكانيكية والكهربائية (SOW 1.2.1)، والمخططات المختومة من الدفاع المدني (1.2.2).$t$, $t$Includes architectural, mechanical and electrical shop drawings (SOW 1.2.1) and Civil Defense–stamped drawings (1.2.2).$t$),
  ($t$8c49bf554e01f561ef79ecc76b04969623e34740d99d2bb8dfeaeda056a926da$t$, $t$تجهيز الموقع وبدء الأعمال (SOW 1.1.1). أسماء لوحة المشروع حسب اتفاقية الشراكة المجتمعية.$t$, $t$Site mobilization (SOW 1.1.1). Project signboard names per the community partnership agreement.$t$),
  ($t$9d67768ba9cbd2b2e30b28c8b849aac9dcf27d9bfa936182a8c43afa5ad40de0$t$, $t$ضمن تجهيز الموقع (SOW 1.1.1).$t$, $t$Part of site mobilization (SOW 1.1.1).$t$),
  ($t$79faf7b3609f1161671ccd20b2d56599dc587550220ec067237954ca6965d238$t$, $t$من مرجعنا: الدراسات والحسابات والاختبارات المعملية لازمة للاعتماد وإن لم ينص عليها نطاق العمل.$t$, $t$From our reference: engineering studies, calculations and laboratory tests are required for approval even though the SOW does not mention them.$t$),
  ($t$4da9f7451a2431f6f5a5ce2ee99e02d85db0afc31439e8192c48424ccdbe03f4$t$, $t$جهاز إشراف مقيم للمقاول طوال مدة التنفيذ: مهندس موقع يغطي الأعمال المعمارية والكهروميكانيكية وأنظمة الحريق، ومسؤول سلامة متفرغ (SOW 1.1.4)؛ والنظافة والحماية أثناء العمل (1.1.2–1.1.3).$t$, $t$Contractor's resident site team throughout the works: a site engineer covering architectural, MEP and fire works, and a full-time safety officer (SOW 1.1.4); cleaning and protection during the works (1.1.2–1.1.3).$t$),
  ($t$1dde2eafc0b14eb3a9f869d6b0e5458c677b7a547c07ddfa748297e0b31477f3$t$, $t$يُنسق مع بند وحدة الحلقة الرئيسية والمحول.$t$, $t$Coordinate with the RMU and transformer item.$t$),
  ($t$f05622a42661057d82283db9475aa947dd676ab5903e5c6da063533dafd113e9$t$, $t$الحفر والردم الإنشائي (SOW 2.1.1–2.1.2).$t$, $t$Excavation and structural fill (SOW 2.1.1–2.1.2).$t$),
  ($t$dc921db35669df51c45a449a73f2f8e8a59af9089facbe82f7e8004204b2059a$t$, $t$معالجة التربة (SOW 2.1.3).$t$, $t$Soil treatment (SOW 2.1.3).$t$),
  ($t$0f58b7ae552e4d4f7c944941fc0d77be137960826dbb9db3d48d9a99f56c07f6$t$, $t$الخرسانة العادية (SOW 3.1.1)، والقواعد المنفصلة والمشتركة والشريطية ورقاب الأعمدة والجدران والميدات والبلاطة الأرضية 150 مم أو حسب التصميم الإنشائي (3.2.1–3.2.4)، وعزل الأعمال الملامسة للتربة (7.1).$t$, $t$Blinding concrete (SOW 3.1.1); isolated, combined and strip foundations, column necks, walls, beams and 150 mm slab on grade or per the structural design (3.2.1–3.2.4); and waterproofing of below-grade works (7.1).$t$),
  ($t$c054af9e3b2e41f2589b484dd74e8e173b2d11aa3fcedb0a9b4520916a85b1df$t$, $t$الجدران والأعمدة (SOW 3.2.5)، والبلاطات المصمتة (Solid Slab) حسب النظام الإنشائي في المخططات بدل البلاطات اللاكمرية (3.2.6)، والسلالم والبسطات (3.2.7)، والعناصر الخرسانية لغرف الكهرباء والمولد والغازات الطبية (3.2.9).$t$, $t$Walls and columns (SOW 3.2.5); solid slabs per the structural system on the drawings instead of flat slabs (3.2.6); stairs and landings (3.2.7); and concrete elements for the electrical, generator and medical gas rooms (3.2.9).$t$),
  ($t$3238d5bd3b69e23ec2879908b9c7e6e2fbc49edadeecd2750e3a2f32ccf38874$t$, $t$خزان مياه الشرب وخزان مياه الحريق خرسانيان حسب المخططات (SOW 3.2.8، 22.1.4)، وعزل الخزانات (7.2)؛ ويُنسق مع بند مضخات الحريق.$t$, $t$Potable water tank and fire water tank, both reinforced concrete per the drawings (SOW 3.2.8, 22.1.4), with tank waterproofing (7.2); coordinate with the fire pumps item.$t$),
  ($t$d5bd154046f2557adb966082b6d5622dbf551624fae9450bcf63f2eb22a0f75d$t$, $t$البلوك الخرساني المفرغ (SOW 4.1) والبلوك المعزول (4.2).$t$, $t$Hollow concrete blocks (SOW 4.1) and insulated blocks (4.2).$t$),
  ($t$cf332bfe14152cf5ad66e639a2da12a42410a04a96527c6e20a57fcfc5958dde$t$, $t$العزل المائي للمناطق الرطبة (SOW 7.3).$t$, $t$Waterproofing of wet areas (SOW 7.3).$t$),
  ($t$49ac40b75addf0d77009e4e5c0f3be8e8fa5a32a18ab651709b43cd4317dca19$t$, $t$نظام عزل الأسطح (SOW 7.4)، والطبقة الحامية النهائية بلاط تيرازو لسطح الروف (9.2.4).$t$, $t$Roof waterproofing system (SOW 7.4), with terrazzo tiles as the final protective layer of the roof deck (9.2.4).$t$),
  ($t$a4eb6b18780568dcf845d0d0dfc0db7a9c39dc7cbdb09e6147e849997c538941$t$, $t$درابزين الدرج والسلم المعدني الخارجي للسطح (SOW قسم 5 — البندان 4.1 و4.2).$t$, $t$Staircase handrail and external steel roof ladder (SOW Div. 5 — items 4.1 and 4.2).$t$),
  ($t$73dbf37c0c68d47cfd87682952f83650a1fb892e3362d6c7e6a61566f9ddbf57$t$, $t$كاسرات الألمنيوم وأغطية الشفتات (SOW قسم 5 — البندان 4.3 و4.4).$t$, $t$Aluminum louvers and shaft flashing (SOW Div. 5 — items 4.3 and 4.4).$t$),
  ($t$35b8b446c24e05be3c13391762127119f1d0385e16a555a3e11130ab5b8799af$t$, $t$الكاسرات وأغطية الفتحات من الألمنيوم$t$, $t$Aluminum Louvers and Flashing$t$),
  ($t$0b801928fb33fe4a7c6d386c16ae5c6e8442fc2c3eaf01804e6905dacae21d9b$t$, $t$توريد وتركيب كاسرات وشبابيك تهوية (Louvers) من الألمنيوم المبثوق المدهون بودرة بوليستر بسماكة لا تقل عن 80 ميكرون باللون المعتمد، بشفرات مانعة لدخول المطر وشبك حماية من الطيور والحشرات، للفتحات الميكانيكية والواجهات حسب المخططات؛ وتوريد وتركيب أغطية وفلاشينج من صفائح الألمنيوم المدهون لتغطية الشفتات والفتحات على السطح وحواف التقاء المواد، بالتثبيت والإحكام بالسيليكون المناسب للأعمال الخارجية؛ مع تقديم العينات ومخططات الورشة للاعتماد قبل التصنيع. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install extruded aluminum louvers, powder-coated polyester at not less than 80 microns in the approved color, with rain-resistant blades and bird and insect screens, for mechanical openings and façades per the drawings; and supply and install painted aluminum sheet covers and flashing for shafts, roof openings and junctions between materials, fixed and sealed with silicone suitable for external works; samples and shop drawings to be submitted for approval before fabrication. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$1a5642cfffe93e41901d0e18d152b440e7458c637908a1340070957ce65100f4$t$, $t$الأبواب المعدنية والخشبية المفردة (SOW 8.1) والمزدوجة (8.2). الأبواب الزجاجية ضمن بند الواجهات والقواطع الزجاجية.$t$, $t$Single (SOW 8.1) and double (8.2) metal and wooden doors. Glass doors are under the glazing and glass partitions item.$t$),
  ($t$c259d5e0788f7dbd6522d807d54d55d003ddb12ec25897db1e61cd5095f3164c$t$, $t$الأبواب المعدنية والخشبية والأقفال$t$, $t$Metal and Wooden Doors and Locks$t$),
  ($t$1e032bf0aa39a73bba8a1d418be31ad49fcf5cf83c985cc9bdef75cffe91b9d0$t$, $t$توريد وتركيب جميع الأبواب المفردة والمزدوجة حسب جدول الأبواب والمخططات: الأبواب المعدنية بضلفة 47 مم من صاج 1.6 مم وحلق 2.0 مم بتشطيب Flush، وحشوة صوف صخري مع مقويات للأبواب المقاومة للحريق (60/90 دقيقة حسب المخطط) وخلايا نحل لغيرها؛ والأبواب الخشبية بضلفة مصمتة (Solid Core) بتشطيب HPL أو قشرة خشبية حسب جدول التشطيبات، مقاومة للصدمات وسهلة التنظيف للمناطق السريرية؛ مع الإكسسوارات والمفصلات والغالقات وأجهزة الخروج Grade 1، ونوافذ الرؤية بزجاج أمان حيث وردت، وحماية Kick Plate بارتفاع لا يقل عن 90 سم (CS Group)؛ وعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل؛ وأبواب مخارج الطوارئ المقاومة للحريق تفتح للخارج بذراع خروج سريع مربوط بإنذار الحريق؛ وأقفال إلكترونية SALTO بقفل Mortise لغرف الكهرباء والاتصالات والميكانيكا والغازات الطبية؛ ونظام مفاتيح ماستر مع صناديق مفاتيح مرقمة. يُعتمد نوع كل باب وقفل قبل التوريد. المصنّعون المعتمدون للأبواب المعدنية: HÖRMANN، الكحيمي، الدريس. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install all single and double doors per the door schedule and drawings: metal doors with 47 mm leaves of 1.6 mm steel sheet and 2.0 mm frames, flush finish, rock-wool infill with reinforcement for fire-rated doors (60/90 minutes per drawing) and honeycomb for others; wooden doors with solid-core leaves finished in HPL or wood veneer per the finishes schedule, impact-resistant and easy to clean for clinical areas; with Grade 1 hardware, hinges, closers and exit devices, vision panels with safety glass where shown, and CS Group kick plates not less than 90 cm high; clear width not less than 95 cm for single and 180 cm for double doors per the Universal Access Guide; fire-rated emergency exit doors opening outward with panic bars linked to the fire alarm; SALTO electronic mortise locks for electrical, communications, mechanical and medical gas rooms; and a master key system with numbered key cabinets. Each door and lock type is approved before supply. Approved metal door manufacturers: HÖRMANN, Al Kuhaimi, Aldrees. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$82f865d7e9fedf8bc9f335c8e8b64454bb0d8bd8a30d258befa4b5d91798de01$t$, $t$الأبواب المبطنة بالرصاص المفردة والمزدوجة (SOW 8.5–8.6)، والنافذة الرصاصية (8.8)، وتبطين جدران غرفة الأشعة (9.5.5).$t$, $t$Single and double lead-lined doors (SOW 8.5–8.6), lead window (8.8) and lead lining of the X-ray room walls (9.5.5).$t$),
  ($t$6f5d6b7caa1f2d78931851e2f3051fc33bdfc1b79b2564be7aebd89f5ffc66e5$t$, $t$التدريع الإشعاعي لغرفة الأشعة (الجدران والأبواب والنافذة)$t$, $t$Radiation Shielding of the X-ray Room (Walls, Doors and Window)$t$),
  ($t$7465e11ece2cf67fd654db5e9d619cee47f93c304bcda2c086af663f4809b5a2$t$, $t$توريد وتركيب التدريع الإشعاعي لغرفة الأشعة حسب دراسة الحماية الإشعاعية المعتمدة: تبطين الجدران (والأسقف والأرضيات حيث تتطلب الدراسة) بألواح الرصاص بالسماكة المكافئة المحددة في الدراسة مع تراكب الفواصل وتغطية فتحات التمديدات؛ وأبواب خشبية مبطنة بالرصاص مفردة ومزدوجة بالمكافئ الرصاصي نفسه بحلوقها وإكسسواراتها؛ ونافذة مراقبة من الزجاج الرصاصي بإطارها؛ ولوحة تحذير ومصباح «الأشعة قيد التشغيل» عند المدخل؛ مع تقديم دراسة الحماية من جهة مؤهلة واعتمادها من هيئة الرقابة النووية والإشعاعية، وقياس مستويات الإشعاع بعد التركيب بتقرير معتمد قبل التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install radiation shielding for the X-ray room per the approved radiation protection study: lead sheet lining of walls (and ceilings and floors where the study requires) at the lead equivalence specified in the study, with overlapping joints and shielded service penetrations; single and double lead-lined wooden doors of the same lead equivalence with frames and hardware; a lead-glass observation window with its frame; and a warning sign and "X-ray in use" light at the entrance; the protection study to be prepared by a qualified party and approved by the Nuclear and Radiological Regulatory Commission, with radiation surveys after installation and an approved report before operation. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$7046fb520d73979f1c4a0f0cc282c3c23f54ab97f2345efb653f9b9eb02e4fe6$t$, $t$الأبواب الأوتوماتيكية (SOW 8.7) بالعدد الوارد في جدول الأبواب.$t$, $t$Automatic doors (SOW 8.7) in the number shown on the door schedule.$t$),
  ($t$60fd03d2f74c17da0bda00ec86750e1ed84f0c1adf47d5e6c26b9006bdb08afb$t$, $t$الأبواب الأوتوماتيكية$t$, $t$Automatic Doors$t$),
  ($t$02ec55459c5cb7ecdee56c3b7dd05750bb1c515db1030974dc4b1c278960fe54$t$, $t$توريد وتركيب الأبواب الانزلاقية الأوتوماتيكية في المواقع المحددة في جدول الأبواب (ومنها المدخل الرئيسي): زجاج مزدوج مقسّى 8+8 مم بفراغ هوائي، وإطار ألمنيوم مدهون بودرة أو أنودايز باللون المعتمد، وعرض ممر صافٍ يسمح بعبور الكراسي المتحركة والنقالات؛ محرك Dorma EL 301 أو ما يعادله لخدمة الاستخدام الكثيف، وحساسات حركة على الوجهين وحساس أمان ضد الاصطدام، ومفتاح أوضاع (أوتوماتيك / مفتوح دائماً / مغلق / اتجاه واحد)؛ وربطها بإنذار الحريق لتفتح فتحاً كاملاً دائماً عند الإنذار (Fail-Safe)، وبطارية احتياطية تشغّلها لمدة لا تقل عن ساعة؛ مع ضمان لا يقل عن سنتين على المحرك ونظام التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install automatic sliding doors at the locations in the door schedule (including the main entrance): 8+8 mm tempered double glazing with air gap, powder-coated or anodized aluminum frame in the approved color, and a clear passage for wheelchairs and stretchers; Dorma EL 301 or equal operator for heavy-duty use, motion sensors on both sides and an anti-collision safety sensor, and a mode switch (automatic / hold open / closed / one way); linked to the fire alarm to open fully on alarm (fail-safe), with a back-up battery operating them for at least one hour; warranty of not less than two years on the operator and control system. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$8fcbb50e7bcf79ce6af3d39fdc893efae295843dcebd5b7c19bb818d5a0631c4$t$, $t$النوافذ CW-01 بمقاس 6.5×0.6 م (28 طقماً) وCW-02 بمقاس 2.0×0.6 م (32 طقماً) (SOW 8.9–8.10)، والجدار الساتر للواجهة الأمامية فقط (8.11)، والقواطع الزجاجية (8.12)، والأبواب الزجاجية المفردة والمزدوجة (8.3–8.4).$t$, $t$Windows CW-01 6.5×0.6 m (28 sets) and CW-02 2.0×0.6 m (32 sets) (SOW 8.9–8.10), curtain wall on the front façade only (8.11), glazed partitions (8.12), and single and double glass doors (8.3–8.4).$t$),
  ($t$5dd9ea44d222f94e9b822b69981c8c1bf0102ed04c894d4a50c2225964692050$t$, $t$لياسة الجدران الداخلية (SOW 9.5.1) ولياسة الواجهات الخارجية (9.5.2).$t$, $t$Interior wall plaster (SOW 9.5.1) and external façade plaster (9.5.2).$t$),
  ($t$71808acd62d63402818c55462b4bc20465760e9240010962c10a479fd21e9b0a$t$, $t$طبقة التسوية (SOW 9.1.1)، والفينيل (9.2.1)، والموكيت للمكاتب وغرف الاجتماعات ومناطق الصلاة (9.2.2)، والإيبوكسي للأرضيات (9.2.3) ولجدران المواقع المحددة (9.5.6).$t$, $t$Screed (SOW 9.1.1), vinyl (9.2.1), carpet for offices, meeting rooms and prayer areas (9.2.2), and epoxy for floors (9.2.3) and for walls where specified (9.5.6).$t$),
  ($t$83dda05fb333dcd2ada7674bcccab94dfd161a6b201db60ffd21c17794d4fc41$t$, $t$بورسلان أرضيات المناطق الرطبة (SOW 9.2.2) وجدرانها (9.5.3)، ورخام كرارا (Carrara) للدرج (9.5.1)، وجرانيت المدخل الأمامي (9.2.5 — المقاس كما ورد في نطاق العمل ويُعتمد من المخططات). تيرازو السطح ضمن بند عزل الأسطح.$t$, $t$Porcelain floor tiles in wet areas (SOW 9.2.2) and wall tiles (9.5.3), Carrara marble for the staircase (9.5.1), and granite for the front entrance (9.2.5 — size as stated in the SOW, to be confirmed from the drawings). Roof terrazzo is under the roof waterproofing item.$t$),
  ($t$9d8bf62ff18bdc360ec0cdf8447d67ae2f904170a67531006928a7161470c6ef$t$, $t$أسقف الجبس (SOW 9.3.1)، وبلاطات الأسقف الصوتية حيث وردت في المخططات (9.3.2).$t$, $t$Gypsum board ceilings (SOW 9.3.1) and acoustic ceiling tiles where shown on the drawings (9.3.2).$t$),
  ($t$dcafd2bd0e84a9116d07220cf1dcef09c3393e69744d3a0cdb5934ccbe48255e$t$, $t$القواطع الجبسية (SOW 9.4.1).$t$, $t$Gypsum board partitions (SOW 9.4.1).$t$),
  ($t$a2d332f653e39a65d40bd5ba9f4b22ae7f42f9c456c4e03fe22ef4499cea5fde$t$, $t$القواطع الجبسية$t$, $t$Gypsum Board Partitions$t$),
  ($t$6e3db1241e3003e636064efd93353a8efae5ea35d37ed74ce03c796876aa47b8$t$, $t$توريد وتركيب القواطع الداخلية من ألواح الجبس على هياكل معدنية مجلفنة بالسماكات وأنواع الألواح المحددة في المخططات (عادي، مقاوم للرطوبة في المناطق الرطبة، مقاوم للحريق حيث يلزم)، بكامل الارتفاع حتى السقف الإنشائي، مع حشوة عازلة للصوت من الصوف الصخري، وتقويات داخلية خلف الأجهزة والخزائن والمعلقات الجدارية، والزوايا المعدنية والمعجون والتجهيز للدهان، وإحكام الفراغات والاختراقات بمواد مقاومة للحريق حيث يلزم. الألواح: USG أو MADA. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install internal partitions of gypsum boards on galvanized steel studs in the thicknesses and board types shown on the drawings (standard, moisture-resistant in wet areas, fire-rated where required), full height up to the structural slab, with rock-wool acoustic infill, internal reinforcement behind equipment, cabinets and wall-mounted items, metal corner beads, jointing and preparation for painting, and sealing of gaps and penetrations with fire-resistant materials where required. Boards: USG or MADA. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$b4298fea110deceec1e75ebdb50c90a0f8fc02bac51c1b00c82095f4f87f928b$t$, $t$دهان الأسقف (SOW 9.3.3) والجدران (9.5.4) والواجهات الخارجية (9.5.2).$t$, $t$Painting of ceilings (SOW 9.3.3), walls (9.5.4) and external façades (9.5.2).$t$),
  ($t$a1b35c7af5ff54a0767b1bb8c0faacdc533bae332fb65e19e104c7890e6454e6$t$, $t$حماية الجدران والدرابزين الجداري (Handrails) وحواجز الاصطدام (Crash Rails) (SOW 10.1.1)، والتكسيات الخشبية حيث وردت (6.6).$t$, $t$Wall protection, wall handrails and crash rails (SOW 10.1.1), and wooden cladding where shown (6.6).$t$),
  ($t$5dc6909cdf3b91a733eb6650730b764e4546d305213ffe1448dd87ecb35c707b$t$, $t$إكسسوارات دورات المياه (SOW 10.4.1).$t$, $t$Toilet accessories (SOW 10.4.1).$t$),
  ($t$b682c456fb935c3611537db1c7112bc821442bc5cdaaa1cb24df840bc062350e$t$, $t$من مرجعنا: متطلبات مكافحة العدوى عند نقاط الرعاية، وإن لم ينص عليها نطاق العمل.$t$, $t$From our reference: infection-control requirements at points of care, even though the SOW does not mention them.$t$),
  ($t$ff2f020a1be622a50d6ba199a14d3ed1714bc7e7a152902526dee4e9bee3a39b$t$, $t$اللوحات الخارجية (SOW 2.2.10) ولوحة اسم المبنى (10.2.2).$t$, $t$External signs (SOW 2.2.10) and building name signage (10.2.2).$t$),
  ($t$b7caa27db3586255352632ff6cef6303a00dd665533dcf5cf0ccd2f9c814491f$t$, $t$اللوحات الداخلية (SOW 10.2.1).$t$, $t$Internal signs (SOW 10.2.1).$t$),
  ($t$f078d5f56bc173f82553a18186995fd48a93c68028127357dd8316a5859fdae1$t$, $t$نجارة SOW 6.1–6.5 و6.7–6.12. التكسيات الخشبية (6.6) ضمن بند حماية الحوائط والديكورات.$t$, $t$Joinery SOW 6.1–6.5 and 6.7–6.12. Wooden cladding (6.6) is under the wall protection and interior decoration item.$t$),
  ($t$31b687ef10de798e624fc53c90632a4a7b464fb240a160c92031bc431e7cdaa7$t$, $t$الكاونترات والخزائن والنجارة الثابتة$t$, $t$Counters, Cabinets and Fixed Joinery$t$),
  ($t$5bd88a27974971fde8cb3f4edfafcb8be09dbdbf3fff5434fbd71664da62bef4$t$, $t$توريد وتركيب الكاونترات والخزائن الثابتة حسب المخططات من خشب شيبورد صناعي مقاوم للرطوبة بحواف ABS وأسطح من الرخام الصناعي (Solid Surface)، بإكسسوارات ألمانية وأدراج بإغلاق هادئ (Soft Close)، ويُعتمد التصميم والعينات من مهندس المشروع، وتشمل: كاونتر الاستقبال بواجهة رخام صناعي مزدوج السماكة وجزء منخفض لا يزيد عن 80 سم لمستخدمي الكراسي المتحركة؛ كاونتر الصيدلية ووحدات أرفف الصيدلية؛ خزائن بمغاسل لغرف الملاحظة وغرف التقييم السريع (RAZ)؛ خزائن المختبر وأسطحه المقاومة للكيماويات؛ كاونتر المقهى؛ خزائن المطبخ؛ أسطح مغاسل دورات المياه (Vanity) بالمغاسل والخلاطات والمرايا؛ أسطح كوريان بخزائن سفلية لغرف الأدوية والأدوات النظيفة والمتسخة؛ وحدات التخزين في المستودعات؛ وحوض ستانلس ستيل بسطحه لغرفة النفايات الطبية. الخلاطات: Ideal Standard أو Grohe حصراً. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install fixed counters and cabinets per the drawings in moisture-resistant engineered chipboard with ABS edging and solid surface tops, with German hardware and soft-close drawers; design and samples approved by the project engineer, including: reception counter with double-thickness solid surface front and a lowered section not higher than 80 cm for wheelchair users; pharmacy counter and pharmacy shelving units; cabinets with sinks for observation rooms and rapid assessment zone (RAZ) rooms; laboratory casework with chemical-resistant tops; café counter; kitchen cabinets; vanity tops in toilets with basins, mixers and mirrors; Corian tops with base cabinets for medication, clean and dirty utility rooms; storage units in stores; and a stainless steel sink with top for the medical waste room. Mixers: Ideal Standard or Grohe only. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$c7f40c5ea47391315f39b6138c10375e9435ee903ee8e16a28ed74d68a81a36a$t$, $t$الستائر الدوارة اليدوية (SOW 10.3.1) وستائر خصوصية المرضى (10.3.2). مكاتب الموظفين والنباتات الداخلية غير مشمولة (الأثاث مستبعد من نطاق العمل).$t$, $t$Manual roller blinds (SOW 10.3.1) and cubicle curtains (10.3.2). Staff desks and indoor plants are not included (furniture is under its own item).$t$),
  ($t$8eb0c95591c8ffd690318a65a484976515838370333ab930c8ce698cc3d7c96c$t$, $t$الستائر الطبية والستائر الدوارة$t$, $t$Medical Cubicle Curtains and Roller Blinds$t$),
  ($t$3f0977f9bd09fd103a560cd95dd6bd448a4e9aad257277e09385dbeed5eeb3cb$t$, $t$توريد وتركيب ستائر خصوصية المرضى (Cubicle Curtains) بأقمشة مخصصة للاستخدام الطبي مقاومة للاشتعال، بسككها السقفية ومنزلقاتها، لغرف الفحص والملاحظة والإجراءات وكبائن العلامات الحيوية حسب المخططات، مع طقمي أقمشة احتياطيين لكل موقع؛ وستائر دوارة (Roller Blinds) يدوية: معتمة (Blackout) لنوافذ العيادات وغرف الفحص، وشفافة (See-Through) للمدخل والمكاتب؛ من مورد معتمد بعد اعتماد العينات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply and install patient privacy (cubicle) curtains in fire-retardant medical-grade fabric with ceiling tracks and runners for examination, observation and procedure rooms and vital-signs cubicles per the drawings, with two spare fabric sets for each location; and manual roller blinds: blackout for clinic and examination room windows, and see-through for the entrance and offices; from an approved supplier after approval of samples. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$c4136f56c4fdb7a1b5da0e92d1e5463731619b4af122c36cc4e149964a25dbc6$t$, $t$مصعد الموظفين GF-16 ومصعد الزوار GF-76 (SOW 14.1–14.2).$t$, $t$Staff elevator GF-16 and visitors elevator GF-76 (SOW 14.1–14.2).$t$),
  ($t$e52f65e589e7a01321329098208f6a1777c46b1502d0700505683f927b166dce$t$, $t$المصاعد$t$, $t$Elevators$t$),
  ($t$188b9c4fdf6f63639e8fd700ee6a8ed67cc6f478bb17ab55589c479415c02fca$t$, $t$توريد وتركيب وتشغيل مصعدين حسب المخططات من Schindler حصراً: مصعد الموظفين (GF-16) بفتحة بئر إنشائية 2.75×3.45 م، ومصعد الزوار (GF-76) بفتحة بئر 2.50×2.80 م، بالحمولات والسرعات ومقاسات الكابينة المناسبة لأبعاد البئر واستخدام المنشأة الصحية وفق كود البناء السعودي، بجميع الإكسسوارات والمفاتيح والتشطيبات الداخلية والديكورات التي يختارها مهندس المشروع، شاملاً تجهيز البئر والتجهيزات الكهربائية والربط بإنذار الحريق (الاستدعاء عند الحريق) والتغذية من المولد الاحتياطي، والاختبار والاعتماد من الجهات المختصة قبل التسليم، والصيانة الوقائية خلال فترة الضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission two elevators per the drawings from Schindler only: staff elevator (GF-16) with a structural shaft opening of 2.75×3.45 m, and visitors elevator (GF-76) with a shaft opening of 2.50×2.80 m, with loads, speeds and car sizes suited to the shaft dimensions and healthcare use per the Saudi Building Code, with all accessories, controls, interior finishes and decoration selected by the project engineer, including shaft preparation, electrical works, fire-alarm link (fire recall) and supply from the standby generator, testing and authority certification before handover, and preventive maintenance during the warranty period. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$67c4f61033f5aa6f2d5a3ff5fa31c4258247b3426cc5dd4d5af530742c8ad623$t$, $t$مواسير الإطفاء (SOW 21.1.1) والمحابس (21.1.2) والرشاشات (21.1.4) ومحبس الإنذار (Alarm Check Valve) (21.1.6) ومحابس المناطق (21.1.7).$t$, $t$Fire-fighting pipes (SOW 21.1.1), valves (21.1.2), sprinklers (21.1.4), alarm check valve (21.1.6) and zone control valves (21.1.7).$t$),
  ($t$3b0bde4a09ae294dea1604c85172e1598e612b9c058412d9614a0d4a7d239536$t$, $t$مضخات الحريق (SOW 21.1.5). خزان الحريق خرساني ضمن بند الخزان الأرضي.$t$, $t$Fire pumps (SOW 21.1.5). The fire tank is reinforced concrete under the ground tank item.$t$),
  ($t$20c2778b9a68c479f077c84b1aec2442f69d700648c9902925b62cb914d8563f$t$, $t$كبائن الخراطيم والطفايات (SOW 21.1.3)، والإطفاء بالغاز النظيف FM-200 للغرف المحددة في المخططات (21.2.1).$t$, $t$Hose cabinets and extinguishers (SOW 21.1.3), and FM-200 clean-agent suppression for the rooms shown on the drawings (21.2.1).$t$),
  ($t$c91f470ce83c317778f66ff837b3a6175e6158d3c67b78c94387868c52cb7967$t$, $t$مواسير المياه الباردة والحارة PPR (SOW 22.1.1–22.1.2) ومحابسها (22.1.3)، ومواسير الصرف UPVC (22.2.1)، وغرف التفتيش للصرف والأمطار (22.2.2)، والجلي تراب (22.2.5)، وخزانات المياه العلوية على السطح (22.1.8).$t$, $t$PPR cold and hot water pipes (SOW 22.1.1–22.1.2) and valves (22.1.3), UPVC drainage pipes (22.2.1), sanitary and storm manholes (22.2.2), gully traps (22.2.5), and roof water tanks (22.1.8).$t$),
  ($t$6f93633d31ba85436e0f7225d9190d7cb65c99385eb9e0da514b1ccbc98361f7$t$, $t$الأطقم الصحية (SOW 22.2.3)، ومواضئ الرجال والنساء بخلاطاتها وتصريفها (22.2.4).$t$, $t$Sanitary fixtures (SOW 22.2.3), and male and female ablution areas with their mixers and drainage (22.2.4).$t$),
  ($t$805cca4bb6fcd765c5971788b6c2921abe4ffb42bb1dde442d2d5d9924828c52$t$, $t$السخانات 30 لتراً (SOW 22.1.5)، ووحدة التيسير (22.1.6)، ومضخات المياه (22.1.7)، ومضخات الري (22.2.3 — الري).$t$, $t$Heaters 30 L (SOW 22.1.5), softener (22.1.6), water supply pumps (22.1.7) and irrigation pumps (22.2.3 — irrigation).$t$),
  ($t$c33ae77a96ec7bbdd184ae03600c9682531883c04c63c52ad9644835571c582b$t$, $t$سخانات المياه ومضخات الضغط والري ومعالجة المياه$t$, $t$Water Heaters, Booster and Irrigation Pumps, and Water Treatment$t$),
  ($t$43e31da8f9f9fbf93fa3004f32b3bea057cd0ccd1cf2ea35e78cde249e4d2f6c$t$, $t$توريد وتركيب وتشغيل سخانات المياه الكهربائية بسعة 30 لتراً (A.O. Smith) للمغاسل ونقاط الاستخدام حسب المخططات، بمفاتيح العزل وصمامات الأمان والتصريف؛ ومجموعة مضخات ضغط (Booster) من Grundfos (CM/CME) من مضختين عاملة واحتياطية بإقلاع متبادل وتحكم بالسرعة وخزان ضغط ولوحة تشغيل بمكونات ABB أو Schneider، بسعة تُحسب من المقاول وتُعتمد؛ ومضخات ري المسطحات الخضراء (Grundfos CM/CME) بمنظم الضغط وفلتر الشوائب ولوحة التحكم؛ ووحدة تيسير المياه (Softener) مزدوجة بسعة تُحسب من تحليل المياه واستهلاك المركز، بإعادة التوليد الآلي وخزان الملح؛ شاملاً القواعد والشاسيه والمحابس ومحابس عدم الرجوع والمواسير، مع تقديم الحسابات للاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission 30-liter electric water heaters (A.O. Smith) for basins and points of use per the drawings, with isolators, safety valves and drains; a Grundfos (CM/CME) booster set of two pumps, duty and standby, with alternating start, speed control, pressure vessel and control panel with ABB or Schneider components, capacity calculated by the contractor and approved; Grundfos (CM/CME) irrigation pumps with pressure regulator, strainer and control panel; and a duplex water softener sized from the water analysis and the center's consumption, with automatic regeneration and brine tank; including bases, skids, valves, check valves and piping, with calculations submitted for approval. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$852e9b868bbf83f60e8e264f0209600fabf834793c9d60176b9e8083dd060b2e$t$, $t$نظام الغازات الطبية كاملاً (SOW 22.3.1–22.3.8).$t$, $t$Complete medical gas system (SOW 22.3.1–22.3.8).$t$),
  ($t$05313232c07c948fa11ebc6cedcead986e4c057da541840fc7df964f1ffcbc99$t$, $t$نظام الغازات الطبية$t$, $t$Medical Gas System$t$),
  ($t$516245f27a074d7ebed19be82663a0455cee7278e4190f44873a939134789516$t$, $t$توريد وتركيب واختبار وتشغيل نظام الغازات الطبية حسب المخططات لخدمة الأكسجين (O2) وأكسيد النيتروز (N2O) والهواء الطبي (MA4) والشفط الطبي (Vacuum) وطرد غازات التخدير (AGSS): مواسير النحاس الطبي المنظفة لخدمة الأكسجين (EN 13348) بأقطار 15 و22 و28 مم بوصلات ملحومة بالفضة تحت النيتروجين؛ وصمامات الكرة الخطية بالأقطار نفسها؛ وصناديق صمامات المناطق (AVSU) لثلاثة غازات ولخمسة غازات بلوحات إنذارها؛ ومخارج الغازات الجدارية بالمعيار البريطاني (BS) للأكسجين وأكسيد النيتروز والهواء الطبي والشفط، ومخارج AGSS بنظام فنتوري؛ ومحطة هواء طبي بضاغطين لولبيين (Duplex Screw) بالمجففات والمرشحات؛ ومحطة شفط طبي مزدوجة (Duplex)؛ ومشعبات الأسطوانات: مشعب أوتوماتيكي للأكسجين 2×4 ولأكسيد النيتروز 2×2، ومشعبات احتياطية للأكسجين 2×2 وللهواء الطبي 2×2 ولأكسيد النيتروز 2×1؛ ووحدات رأس السرير (Bed Head Units) لغرف الملاحظة بمخارج الغازات والكهرباء والإنارة ونداء التمريض؛ وتجهيز غرفة الغازات الطبية وتهويتها وتخزين الأسطوانات؛ مع الاختبارات حسب HTM 02-01 أو NFPA 99 (الضغط، التسرب، التقاطع، النقاء، تحديد الهوية) بشهادة اعتماد من طرف ثالث قبل التشغيل. المصنّعون المعتمدون: BeaconMedaes أو Amico أو Dräger للشبكة والمخارج والصناديق والمشعبات، وBeaconMedaes أو Atlas Copco لمحطتي الهواء والشفط. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install, test and commission the medical gas system per the drawings for oxygen (O2), nitrous oxide (N2O), medical air (MA4), medical vacuum and anaesthetic gas scavenging (AGSS): oxygen-cleaned medical copper pipes (EN 13348) of 15, 22 and 28 mm with silver-brazed joints under nitrogen; line ball valves of the same sizes; area valve service units (AVSU) for three gases and five gases with their alarm panels; BS-standard wall outlets for oxygen, nitrous oxide, medical air and vacuum, and venturi AGSS outlets; a medical air plant with duplex screw compressors, dryers and filters; a duplex medical vacuum plant; cylinder manifolds: automatic oxygen 2×4 and nitrous oxide 2×2, and back-up manifolds for oxygen 2×2, medical air 2×2 and nitrous oxide 2×1; bed head units for observation rooms with gas outlets, power, lighting and nurse call; and preparation and ventilation of the medical gas room and cylinder storage; with tests per HTM 02-01 or NFPA 99 (pressure, leakage, cross-connection, purity, identification) and third-party certification before operation. Approved manufacturers: BeaconMedaes, Amico or Dräger for pipeline, outlets, valve boxes and manifolds; BeaconMedaes or Atlas Copco for the air and vacuum plants. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$2c0531245cdc3f2bc91d11ef88b4dee68a6a738b6032c2b07a89a93d755bbce0$t$, $t$وحدات الهواء النقي DX (SOW 23.1)، ووحدات FCU DX (23.2)، وCAV/VAV (23.4)، والناشرات (23.5)، وشبكات الهواء النقي (23.6)، والمخمدات (23.7)، ومجاري الهواء (23.8)، وأجهزة مراقبة فرق الضغط لغرف العزل والإنعاش والإجراءات (23.9). الموازنة ضمن بند الاختبار والتشغيل.$t$, $t$DX fresh air units (SOW 23.1), DX FCUs (23.2), CAV/VAV (23.4), air outlets (23.5), fresh air louvers (23.6), dampers (23.7), ductwork (23.8), and DPMs for isolation, resuscitation and procedure rooms (23.9). Balancing is under the testing and commissioning item.$t$),
  ($t$f872b13eb671eba366596fd6c3ea1c02c44c9072456e834c118040393fd894ac$t$, $t$وحدات الهواء النقي ووحدات التكييف (DX) ومجاري الهواء$t$, $t$Fresh Air Units, DX Units and Ductwork$t$),
  ($t$13917cfa8ae92e7f5240f6a1b85441db6a2b0fa3bf4e37db6e7e6845247fd17a$t$, $t$توريد وتركيب وتشغيل منظومة التكييف حسب المخططات وجدول المعدات: وحدات الهواء النقي (Fresh Air Units) بنظام التمدد المباشر (DX)، ووحدات الملفات (FCU) بنظام DX بوحداتها الخارجية، وصناديق التدفق الثابت والمتغير (CAV/VAV)، بالسعات ومعدلات الهواء حسب حساب أحمال التبريد على 46°م ومعدلات تغيير الهواء وفروق الضغط وفق ASHRAE 170، بفلاتر عالية الكفاءة متوافقة مع ASHRAE 170 وفلاتر أولية قابلة للغسيل ومصيدة رمل عند مآخذ الهواء الخارجي، ومصائد التكثف وعوازل الاهتزاز؛ ومجاري الهواء (تغذية وراجع وهواء نقي) من الصاج المجلفن عيار 24 بوصلات مرنة مقاومة للاشتعال، وعزل صوتي داخلي غير ليفي، وعزل فيبرجلاس داخلي 48 كجم/م³ سماكة 1 بوصة، وخارجي 64 كجم/م³ سماكة 1.5 بوصة مغلف بألمنيوم 0.8 مم على السطح؛ ومخمدات تحكم بالهواء Opposed Blade، ومخمدات حريق ودخان بتصنيف ساعتين معتمدة UL/FM بصناديق فحصها؛ والناشرات وشبكات الراجع وشبكات الهواء النقي (Louvers)؛ وأجهزة مراقبة فرق الضغط (DPM) بشاشة وإنذار عند غرف العزل والإنعاش والإجراءات؛ وفق ASHRAE وSMACNA وNFPA؛ واختبار المجاري بالدخان والتشغيل التجريبي. الماركات المعتمدة للوحدات: York أو LG أو Gree. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission the HVAC system per the drawings and equipment schedule: DX fresh air units, DX fan coil units (FCU) with their outdoor units, and constant/variable air volume boxes (CAV/VAV), with capacities and airflows per cooling load calculations at 46°C and air change rates and pressure relationships per ASHRAE 170, with high-efficiency filters compliant with ASHRAE 170, washable pre-filters and sand traps at outdoor air intakes, condensate traps and vibration isolators; supply, return and fresh air ductwork of 24-gauge galvanized steel with fire-retardant flexible connectors, non-fibrous internal acoustic lining, internal fiberglass insulation 48 kg/m³ 1 inch thick, and external 64 kg/m³ 1.5 inch thick aluminum-clad 0.8 mm on the roof; opposed-blade volume dampers and UL/FM two-hour fire and smoke dampers with access panels; diffusers, return grilles and fresh air louvers; differential pressure monitors (DPM) with display and alarm at isolation, resuscitation and procedure rooms; per ASHRAE, SMACNA and NFPA; with duct smoke testing and trial operation. Approved unit brands: York, LG or Gree. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$0dc99a96824b15d6a2679d103b5ff201d3c730b742af517fd373ab5ed7a01203$t$, $t$مراوح الشفط (SOW 23.3).$t$, $t$Exhaust fans (SOW 23.3).$t$),
  ($t$9cf60b2a1cec30d49f5b0c935355764d9fd45a0a78f3abb47f893091f71d63c5$t$, $t$مراوح الشفط$t$, $t$Exhaust Fans$t$),
  ($t$c6f46690b867ed726e6541466fc0fa307f5f6b007428b25036b16e3a25ecb0d5$t$, $t$توريد وتركيب وتشغيل مراوح الشفط حسب جدول المعدات: مراوح سطحية Downblast Centrifugal (Greenheck أو Loren Cook) لدورات المياه وغرف النظافة والنفايات الطبية والميكانيكا وغرف العزل حيث وردت، بتشغيل مستمر على قواعد أصلية وعوازل اهتزاز وصمام عدم رجوع، ودكت مستقل لكل دورة مياه حتى السطح وأكمام حريق ومانع حريق عند اختراق البلاطات؛ وربط المراوح بنظام إدارة المبنى وإنذار الحريق حسب مصفوفة التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission exhaust fans per the equipment schedule: roof-mounted downblast centrifugal fans (Greenheck or Loren Cook) for toilets, janitor rooms, medical waste and mechanical rooms and isolation rooms where shown, in continuous operation on original bases with vibration isolators and backdraft dampers, a dedicated duct for each toilet up to the roof, and fire sleeves and firestopping at slab penetrations; with fans linked to the BMS and fire alarm per the cause-and-effect matrix. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$7ade6b4f93cba83ceb6819f60ae48abb1c82b98b40137426dc79e59a147900f3$t$, $t$نظام إدارة المبنى (SOW 25.1).$t$, $t$Building management system (SOW 25.1).$t$),
  ($t$5d8d811bf229af773fc33ebab99d6935c0a06686bc7e0da3482ec49704c94ab1$t$, $t$نظام إدارة المبنى (BMS)$t$, $t$Building Management System (BMS)$t$),
  ($t$db9a0d6bbeedf8327c026d44b2b727cbf1a7efe2dbcc0f86a963cebe3a642a65$t$, $t$توريد وتركيب وتشغيل نظام إدارة المبنى (BMS) متكامل: وحدات التحكم الرقمي المباشر (DDC) والحساسات والمشغلات والثرموستات، وواجهات الربط مع وحدات التكييف ومراوح الشفط والمضخات والمولد ومفتاح التحويل الآلي وخزانات المياه وأجهزة مراقبة فرق الضغط وحالة إنذار الحريق، ومحطة عمل مركزية بالبرامج والطابعة، والمواسير والأسلاك؛ مع برمجة الجداول والإنذارات والتقارير، وتقديم قائمة النقاط (Points List) للاعتماد قبل التنفيذ، والاختبار والتشغيل والتدريب. من مصنّع تُقدَّم بياناته للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission an integrated building management system (BMS): direct digital controllers (DDC), sensors, actuators and thermostats, interfaces with HVAC units, exhaust fans, pumps, generator, automatic transfer switch, water tanks, differential pressure monitors and fire-alarm status, a central workstation with software and printer, and conduits and wiring; with programming of schedules, alarms and reports, a points list submitted for approval before execution, testing, commissioning and training. From a manufacturer whose data is submitted for approval before supply. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$22d07db674c8f08db6c0c821884a63c9b3a70feb81dd8fb52d376a0cc3face4e$t$, $t$وحدة RMU (SOW 26.1)، والمحول (26.2)، وكابلات الجهد المتوسط (26.10). يُنسق مع بند توصيل الخدمات العامة.$t$, $t$RMU (SOW 26.1), transformer (26.2) and MV cables (26.10). Coordinate with the public utility connections item.$t$),
  ($t$0d26c540cecfccb5e99eed1b3c2ae2830c83456313b2593428979b40e56f0d6a$t$, $t$وحدة الحلقة الرئيسية (RMU) والمحول وكابلات الجهد المتوسط$t$, $t$Ring Main Unit (RMU), Transformer and MV Cables$t$),
  ($t$c165ea53d5b5d2e7d9294208a5a7d0fd6703627f8b6f425b68577c9d08e86b3d$t$, $t$توريد وتركيب واختبار وتشغيل وحدة الحلقة الرئيسية (RMU) للجهد المتوسط، ومحول التوزيع بالقدرة حسب دراسة الأحمال المعتمدة ونسبة الاحتياطي، وكابلات الجهد المتوسط بنهاياتها ووصلاتها، وفق اشتراطات الشركة السعودية للكهرباء ومواصفاتها؛ شاملاً غرفة المحول أو قاعدته وفتحات التهوية والتأريض والحماية، والاختبارات المصنعية والموقعية، والتسليم والتوصيل مع الشركة. المصنّعون المعتمدون من القائمة المعتمدة لدى الشركة السعودية للكهرباء: وحدة الحلقة Lucy أو Schneider أو Hitachi Energy، والمحول الفنار أو الشركة السعودية للمحولات أو Hitachi Energy. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install, test and commission the medium-voltage ring main unit (RMU), the distribution transformer rated per the approved load study and spare margin, and the medium-voltage cables with terminations and joints, per the requirements and specifications of the Saudi Electricity Company; including the transformer room or plinth, ventilation openings, earthing and protection, factory and site tests, and handover and connection with the company. Approved manufacturers from the Saudi Electricity Company approved list: RMU by Lucy, Schneider or Hitachi Energy; transformer by Alfanar, Saudi Transformers Company or Hitachi Energy. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$da4648dac2fb5090e7876052d57709da57b7a7a5bf82da1c165e8b11f540883f$t$, $t$المولد (SOW 26.3) ومفتاح التحويل الآلي (26.4).$t$, $t$Generator (SOW 26.3) and automatic transfer switch (26.4).$t$),
  ($t$af96a52d278052b7b4c4de7c3f7c71062634876ed9150046d409261a615e111a$t$, $t$المولد الاحتياطي ومفتاح التحويل الآلي$t$, $t$Standby Generator and Automatic Transfer Switch$t$),
  ($t$7af0de717385c8d623b4fdd0420aae07c94c1bab05934bec47a59cbd0b52fd7f$t$, $t$توريد وتركيب وتشغيل مولد ديزل احتياطي بمظلة صامتة بالقدرة حسب دراسة الأحمال الأساسية للمركز (الإنارة والقوى الحرجة، التكييف للمناطق الحرجة، مضخات الحريق والمياه، المصاعد، الغازات الطبية، الأنظمة التقنية) مع احتياطي مستقبلي، بخزان وقود يكفي التشغيل المتواصل للمدة المعتمدة، ونظام العادم والكاتم، والقاعدة وعوازل الاهتزاز، ولوحة التحكم والمراقبة عن بعد والربط بنظام إدارة المبنى؛ ومفتاح التحويل الآلي (ATS) بالسعة المناسبة؛ مع اختبار التحميل الكامل بحمل صناعي (Load Bank) وزمن التحويل، وفق NFPA 110 ومتطلبات الدفاع المدني. المصنّعون المعتمدون: المولد Cummins أو Caterpillar أو FG Wilson أو MTU، ومفتاح التحويل ASCO أو Cummins أو ABB. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and commission a standby diesel generator in a silent canopy rated per the study of the center's essential loads (critical lighting and power, HVAC for critical areas, fire and water pumps, elevators, medical gases, technical systems) with future spare capacity, with a fuel tank for continuous operation for the approved duration, exhaust system and silencer, base and vibration isolators, control panel with remote monitoring and BMS link; and an automatic transfer switch (ATS) of suitable rating; with full-load testing on a load bank and transfer-time testing, per NFPA 110 and Civil Defense requirements. Approved manufacturers: generator by Cummins, Caterpillar, FG Wilson or MTU; transfer switch by ASCO, Cummins or ABB. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$81fc7dcea46c7d666e07ba6d341767733d27f72d59e22d8cb2417b2b59660cfd$t$, $t$اللوحات الرئيسية والفرعية (SOW 26.5)، ولوحات MCC (26.6)، ولوحات الإنارة والقوى والتكييف (26.7)، وكابلات الجهد المنخفض (26.9). سعة القاطع الرئيسي حسب دراسة الأحمال المعتمدة لهذا المركز.$t$, $t$Main and sub-main panels (SOW 26.5), MCC (26.6), lighting, power and AC panel boards (26.7) and LV cables (26.9). Main breaker rating per the approved load study for this center.$t$),
  ($t$bfafa68169c8ff51af5bce19cbf15296066e8cbfbb83d1c1e45d217ede58b2bf$t$, $t$لوحة العزل الطبية (SOW 26.8).$t$, $t$Isolation panel (SOW 26.8).$t$),
  ($t$47a91678936884aa5b0b5416f968b2b8efd5e2a1a0a726d2aeb2c76d30f317c5$t$, $t$لوحات الطاقة المعزولة الطبية (IPS)$t$, $t$Medical Isolated Power Supply Panels (IPS)$t$),
  ($t$45b1edf0bcfe8ef53f0f1b0572b422b0b99ca88c439d297a22feeb805bb1e9df$t$, $t$توريد وتركيب واختبار لوحات الطاقة المعزولة الطبية (IPS) للمواقع الطبية المحددة في المخططات (مثل غرف الإنعاش والإجراءات) وفق IEC 60364-7-710: محول عزل طبي، وجهاز مراقبة العزل (LIM) بإنذار محلي، ولوحة إنذار عن بعد في محطة التمريض، والقواطع والتأريض المتساوي الجهد للأجهزة الطبية؛ مع اختبارات الأداء وشهادة المصنع. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, $t$Supply, install and test medical isolated power supply (IPS) panels for the medical locations shown on the drawings (such as resuscitation and procedure rooms) per IEC 60364-7-710: medical isolation transformer, line isolation monitor (LIM) with local alarm, remote alarm panel at the nurse station, breakers and equipotential bonding for medical equipment; with performance tests and the manufacturer's certificate. Including everything required to complete the works fully ready for operation in accordance with the drawings and specifications, even if not expressly stated.$t$),
  ($t$b5297058c2e05a45062a7f794b582745a352199beaed77709e22723f4696d9e7$t$, $t$المقابس وصناديق الأرضيات والمخارج (SOW 26.13)، ووحدات الإنارة (26.14)، وإنارة المسطحات (26.15) والواجهات (26.16)، ومفاتيح الفصل لجميع المعدات الميكانيكية والطبية (26.17)، وغرف التفتيش الكهربائية (26.18).$t$, $t$Power sockets, floor boxes and outlets (SOW 26.13), lighting fixtures (26.14), landscape (26.15) and façade lighting (26.16), disconnect switches for all mechanical and medical equipment (26.17), and electrical manholes (26.18).$t$),
  ($t$72d57d4b378a25ed6c8efd2dd7577e56691a8ef362b74734227ad0d618ffef2c$t$, $t$التأريض للكهرباء والتيار الخفيف (SOW 26.11)؛ ويشمل نظام الحماية من الصواعق وفق IEC 62305 بمانعات الصواعق والموصلات النازلة ونقاط الاختبار المربوطة بالتأريض (26.12).$t$, $t$Earthing for power and low-current systems (SOW 26.11); including a lightning protection system per IEC 62305 with air terminals, down conductors and test points bonded to the earthing (26.12).$t$),
