-- 0082: مصنّعون معتمدون للغازات الطبية والمولدات ووحدات الحلقة والمحولات (المواد M-39..41، بطاقات G-30..32، بندا المقطوعية LS-95/96)، توضيح G-22، ربط بنود جدول فاطمة العفالق، والترجمة الإنجليزية لنصوصه. المولّد tools/boq/mk82.py
update public.guide_cards set approved = $t$York DEH 360 (وحدات Package) · LG / Gree / York (الوحدات المنفصلة وDX) · Greenheck / Loren Cook · Armaflex$t$ where key = 'G-22' and approved = $t$York DEH 360 · LG / Gree / York · Greenheck / Loren Cook · Armaflex$t$;
update public.boq_lines set ls_code = 'LS-95', descr = $t$توريد وتركيب واختبار وتشغيل وحدة الحلقة الرئيسية (RMU) للجهد المتوسط، ومحول التوزيع بالقدرة حسب دراسة الأحمال المعتمدة ونسبة الاحتياطي، وكابلات الجهد المتوسط بنهاياتها ووصلاتها، وفق اشتراطات الشركة السعودية للكهرباء ومواصفاتها؛ شاملاً غرفة المحول أو قاعدته وفتحات التهوية والتأريض والحماية، والاختبارات المصنعية والموقعية، والتسليم والتوصيل مع الشركة. المصنّعون المعتمدون من القائمة المعتمدة لدى الشركة السعودية للكهرباء: وحدة الحلقة Lucy أو Schneider أو Hitachi Energy، والمحول الفنار أو الشركة السعودية للمحولات أو Hitachi Energy. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$ where boq_id = (select id from public.boqs where name = 'مقطوعية — مركز فاطمة العفالق' order by created_at limit 1) and title = $t$وحدة الحلقة الرئيسية (RMU) والمحول وكابلات الجهد المتوسط$t$ and ls_code is null;
update public.boq_lines set ls_code = 'LS-96', descr = $t$توريد وتركيب وتشغيل مولد ديزل احتياطي بمظلة صامتة بالقدرة حسب دراسة الأحمال الأساسية للمركز (الإنارة والقوى الحرجة، التكييف للمناطق الحرجة، مضخات الحريق والمياه، المصاعد، الغازات الطبية، الأنظمة التقنية) مع احتياطي مستقبلي، بخزان وقود يكفي التشغيل المتواصل للمدة المعتمدة، ونظام العادم والكاتم، والقاعدة وعوازل الاهتزاز، ولوحة التحكم والمراقبة عن بعد والربط بنظام إدارة المبنى؛ ومفتاح التحويل الآلي (ATS) بالسعة المناسبة؛ مع اختبار التحميل الكامل بحمل صناعي (Load Bank) وزمن التحويل، وفق NFPA 110 ومتطلبات الدفاع المدني. المصنّعون المعتمدون: المولد Cummins أو Caterpillar أو FG Wilson أو MTU، ومفتاح التحويل ASCO أو Cummins أو ABB. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$ where boq_id = (select id from public.boqs where name = 'مقطوعية — مركز فاطمة العفالق' order by created_at limit 1) and title = $t$المولد الاحتياطي ومفتاح التحويل الآلي$t$ and ls_code is null;
update public.boq_lines set descr = $t$توريد وتركيب واختبار وتشغيل نظام الغازات الطبية حسب المخططات لخدمة الأكسجين (O2) وأكسيد النيتروز (N2O) والهواء الطبي (MA4) والشفط الطبي (Vacuum) وطرد غازات التخدير (AGSS): مواسير النحاس الطبي المنظفة لخدمة الأكسجين (EN 13348) بأقطار 15 و22 و28 مم بوصلات ملحومة بالفضة تحت النيتروجين؛ وصمامات الكرة الخطية بالأقطار نفسها؛ وصناديق صمامات المناطق (AVSU) لثلاثة غازات ولخمسة غازات بلوحات إنذارها؛ ومخارج الغازات الجدارية بالمعيار البريطاني (BS) للأكسجين وأكسيد النيتروز والهواء الطبي والشفط، ومخارج AGSS بنظام فنتوري؛ ومحطة هواء طبي بضاغطين لولبيين (Duplex Screw) بالمجففات والمرشحات؛ ومحطة شفط طبي مزدوجة (Duplex)؛ ومشعبات الأسطوانات: مشعب أوتوماتيكي للأكسجين 2×4 ولأكسيد النيتروز 2×2، ومشعبات احتياطية للأكسجين 2×2 وللهواء الطبي 2×2 ولأكسيد النيتروز 2×1؛ ووحدات رأس السرير (Bed Head Units) لغرف الملاحظة بمخارج الغازات والكهرباء والإنارة ونداء التمريض؛ وتجهيز غرفة الغازات الطبية وتهويتها وتخزين الأسطوانات؛ مع الاختبارات حسب HTM 02-01 أو NFPA 99 (الضغط، التسرب، التقاطع، النقاء، تحديد الهوية) بشهادة اعتماد من طرف ثالث قبل التشغيل. المصنّعون المعتمدون: BeaconMedaes أو Amico أو Dräger للشبكة والمخارج والصناديق والمشعبات، وBeaconMedaes أو Atlas Copco لمحطتي الهواء والشفط. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$ where boq_id = (select id from public.boqs where name = 'مقطوعية — مركز فاطمة العفالق' order by created_at limit 1) and ls_code = 'LS-76' and descr not like '%BeaconMedaes%';
on conflict (k) do nothing;
